package com.bank.solid;

import java.math.BigDecimal;
import java.util.logging.*;

public class SolidDemo {
    private static final Logger log = Logger.getLogger(SolidDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // DIP: inject abstractions, do not 'new' them inside the service
        Notifier notifier = new SmsNotifier();
        FeeStrategy fee = new EquityFee();                 // OCP: swappable per type
        TransferValidator validator = new TransferValidator(); // SRP: one job
        TransferService service = new TransferService(validator, fee, notifier);

        BigDecimal rentAmount = new BigDecimal("50000");
        service.transfer(rajesh, priya, rentAmount);
        log.info(() -> "Rajesh balance: Rs." + rajesh.getBalance());
        log.info(() -> "Priya balance : Rs." + priya.getBalance());
    }
}

// ─── SRP: validation is its own class ───
class TransferValidator {
    void validate(Account from, BigDecimal amt) {
        if (amt.signum() <= 0) throw new IllegalArgumentException("Amount must be positive");
        if (from.getBalance().compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds");
    }
}

// ─── OCP: fee is an abstraction; add a type = add a class ───
interface FeeStrategy { BigDecimal fee(BigDecimal amount); }
class EquityFee implements FeeStrategy {
    public BigDecimal fee(BigDecimal amount) { return amount.multiply(new BigDecimal("0.0010")); }
}
class FxFee implements FeeStrategy {
    public BigDecimal fee(BigDecimal amount) { return amount.multiply(new BigDecimal("0.0025")); }
}

// ─── DIP: depend on this abstraction, inject the impl ───
interface Notifier { void notify(String msg); }
class SmsNotifier implements Notifier {
    public void notify(String msg) { Logger.getLogger("SMS").info(msg); }
}

// ─── ISP: small role interfaces instead of one fat Account interface ───
interface InterestBearing { BigDecimal calculateInterest(); }
interface Tradable { void placeOrder(String symbol, int qty); }

// ─── LSP-safe Account: debit means debit, no surprise overrides ───
class Account {
    private final String accountId, holderName; private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; } String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) {
        if (balance.compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds");
        balance = balance.subtract(amt);
    }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
}

// ─── SRP: service only orchestrates; it delegates to injected collaborators ───
class TransferService {
    private final TransferValidator validator;
    private final FeeStrategy feeStrategy;
    private final Notifier notifier;
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    TransferService(TransferValidator v, FeeStrategy f, Notifier n) {
        this.validator = v; this.feeStrategy = f; this.notifier = n;
    }
    void transfer(Account from, Account to, BigDecimal amount) {
        validator.validate(from, amount);                 // SRP
        BigDecimal fee = feeStrategy.fee(amount);          // OCP
        BigDecimal total = amount.add(fee);
        validator.validate(from, total);
        from.debit(total);
        to.credit(amount);
        log.info(() -> "Transferred Rs." + amount + " (fee Rs." + fee + ") "
            + from.getAccountId() + "->" + to.getAccountId());
        notifier.notify("Dear " + from.getHolderName() + ", Rs." + amount + " transferred.");  // DIP
    }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
