// ─── File: SingletonDemo.java ───
package com.bank.singleton;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class SingletonDemo {
    private static final Logger log = Logger.getLogger(SingletonDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        log.info(() -> "Eager  equal: " + (EagerConfig.getInstance() == EagerConfig.getInstance()));
        log.info(() -> "Sync   equal: " + (SyncConfig.getInstance() == SyncConfig.getInstance()));
        log.info(() -> "DCL    equal: " + (DclConfig.getInstance() == DclConfig.getInstance()));
        log.info(() -> "Holder equal: " + (HolderConfig.getInstance() == HolderConfig.getInstance()));
        log.info(() -> "Enum   equal: " + (EnumConfig.INSTANCE == EnumConfig.INSTANCE));

        // Prove thread-safety: 50 threads race to get the holder instance
        ExecutorService pool = Executors.newFixedThreadPool(10);
        Set<Integer> identities = ConcurrentHashMap.newKeySet();
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < 50; i++)
            futures.add(pool.submit(() -> identities.add(System.identityHashCode(HolderConfig.getInstance()))));
        for (Future<?> f : futures) f.get();
        pool.shutdown();
        log.info(() -> "Distinct holder instances across 50 threads: " + identities.size() + " (expect 1)");

        // Use the enum singleton
        EnumConfig.INSTANCE.setEquityFeeRate(new BigDecimal("0.0010"));
        log.info(() -> "Equity fee rate from enum singleton: " + EnumConfig.INSTANCE.getEquityFeeRate());
    }
}

// ─── EAGER: created at class load, thread-safe, not lazy ───
class EagerConfig {
    private static final EagerConfig INSTANCE = new EagerConfig();
    private EagerConfig() {}
    static EagerConfig getInstance() { return INSTANCE; }
}

// ─── SYNCHRONIZED GETTER: lazy, but locks every call ───
class SyncConfig {
    private static SyncConfig instance;
    private SyncConfig() {}
    static synchronized SyncConfig getInstance() {
        if (instance == null) instance = new SyncConfig();
        return instance;
    }
}

// ─── DOUBLE-CHECKED LOCKING: volatile is mandatory ───
class DclConfig {
    private static volatile DclConfig instance;   // volatile prevents partial-object visibility
    private DclConfig() {}
    static DclConfig getInstance() {
        if (instance == null) {                    // first check, no lock
            synchronized (DclConfig.class) {
                if (instance == null)              // second check, under lock
                    instance = new DclConfig();
            }
        }
        return instance;
    }
}

// ─── BILL PUGH HOLDER: lazy + thread-safe via class loading, no sync ───
class HolderConfig {
    private HolderConfig() {}
    private static class Holder { static final HolderConfig INSTANCE = new HolderConfig(); }
    static HolderConfig getInstance() { return Holder.INSTANCE; }
}

// ─── ENUM SINGLETON: concise, serialization-/reflection-safe (preferred) ───
enum EnumConfig {
    INSTANCE;
    private BigDecimal equityFeeRate = BigDecimal.ZERO;
    public void setEquityFeeRate(BigDecimal r) { this.equityFeeRate = r; }
    public BigDecimal getEquityFeeRate() { return equityFeeRate; }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
```

Note: the Bill Pugh idiom deliberately uses a private static inner Holder class — that nested class is the mechanism of the pattern itself and is the accepted exception; all real services and domain types in the wider project remain top-level classes.

