// ─── File: FactoryDemo.java ───
package com.bank.factory;

import java.math.BigDecimal;
import java.util.*;
import java.util.function.Supplier;
import java.util.logging.*;

public class FactoryDemo {
    private static final Logger log = Logger.getLogger(FactoryDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        NotificationService service = new NotificationService();
        BigDecimal amount = new BigDecimal("50000");

        // Rajesh prefers SMS — factory returns SmsChannel without us typing 'new'
        service.alert(ChannelType.SMS, "+91-98765-00001",
            "Dear Rajesh, Rs." + amount + " debited from SAV2001.");

        // Priya prefers EMAIL — same code path, different concrete product
        service.alert(ChannelType.EMAIL, "priya@example.com",
            "Dear Priya, Rs." + amount + " credited to CUR3001.");

        // New channel added later: PUSH — existing code untouched
        service.alert(ChannelType.PUSH, "device-token-xyz",
            "Transaction alert: Rs." + amount);
    }
}

enum ChannelType { SMS, EMAIL, PUSH }

// ─── PRODUCT INTERFACE ───
interface NotificationChannel { void send(String to, String message); }

// ─── CONCRETE PRODUCTS ───
class SmsChannel implements NotificationChannel {
    public void send(String to, String message) {
        Logger.getLogger("SMS").info("SMS to " + to + ": " + message);
    }
}
class EmailChannel implements NotificationChannel {
    public void send(String to, String message) {
        Logger.getLogger("EMAIL").info("EMAIL to " + to + ": " + message);
    }
}
class PushChannel implements NotificationChannel {
    public void send(String to, String message) {
        Logger.getLogger("PUSH").info("PUSH to " + to + ": " + message);
    }
}

// ─── THE FACTORY: map of suppliers (modern style, no switch) ───
class ChannelFactory {
    private static final Map<ChannelType, Supplier<NotificationChannel>> REGISTRY = new EnumMap<>(ChannelType.class);
    static {
        REGISTRY.put(ChannelType.SMS, SmsChannel::new);
        REGISTRY.put(ChannelType.EMAIL, EmailChannel::new);
        REGISTRY.put(ChannelType.PUSH, PushChannel::new);
    }
    static NotificationChannel create(ChannelType type) {
        Supplier<NotificationChannel> s = REGISTRY.get(type);
        if (s == null) throw new IllegalArgumentException("Unknown channel: " + type);
        return s.get();
    }
}

// ─── SERVICE: depends on factory + interface, never on concrete classes ───
class NotificationService {
    private static final Logger log = Logger.getLogger(NotificationService.class.getName());
    void alert(ChannelType type, String to, String message) {
        NotificationChannel channel = ChannelFactory.create(type);
        log.info(() -> "Using channel: " + channel.getClass().getSimpleName());
        channel.send(to, message);
    }
}

class BankLogFormatter extends Formatter {
