    public static void main(String[] args) throws Exception {
        log.info(() -> "Before first getInstance: holder created? " + HolderAuditLedger.wasCreated());

        // 100 threads race to get the lazy Bill Pugh instance
        ExecutorService pool = Executors.newFixedThreadPool(16);
        Set<Integer> identities = ConcurrentHashMap.newKeySet();
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < 100; i++)
            futures.add(pool.submit(() -> identities.add(System.identityHashCode(HolderAuditLedger.getInstance()))));
        for (Future<?> f : futures) f.get();
        pool.shutdown();

        log.info(() -> "After getInstance: holder created? " + HolderAuditLedger.wasCreated());
        log.info(() -> "Distinct instances across 100 threads: " + identities.size() + " (expect 1)");

        // Record transactions through the single ledger
        HolderAuditLedger.getInstance().append("TRANSFER SAV2001->CUR3001 Rs.50000");
        HolderAuditLedger.getInstance().append("TRANSFER CUR3001->SAV2001 Rs.10000");
        log.info(() -> "Holder ledger entries: " + HolderAuditLedger.getInstance().size());

        // Enum ledger: robust alternative
        EnumAuditLedger.INSTANCE.append("FEE DEBIT SAV2001 Rs.50");
        log.info(() -> "Enum ledger entries: " + EnumAuditLedger.INSTANCE.size());
    }
}

// ─── BILL PUGH HOLDER: lazy + thread-safe, no synchronized/volatile ───
class HolderAuditLedger {
    private final List<String> entries = Collections.synchronizedList(new ArrayList<>());
    private HolderAuditLedger() { Logger.getLogger("LEDGER").info("AuditLedger CONSTRUCTED (lazy)"); }

    private static class Holder {
        static final HolderAuditLedger INSTANCE = new HolderAuditLedger();
        static boolean loaded = true;
    }
    static HolderAuditLedger getInstance() { return Holder.INSTANCE; }
    // only to demonstrate laziness in the demo
    static boolean wasCreated() {
        try {
            Class<?> c = Class.forName("com.bank.auditsingleton.HolderAuditLedger$Holder", false,
                HolderAuditLedger.class.getClassLoader());
            return c != null && isInitialized();
        } catch (Throwable t) { return false; }
    }
    private static boolean isInitialized() { return INITIALIZED; }
    private static volatile boolean INITIALIZED = false;
    { INITIALIZED = true; } // instance init sets flag only when an instance is built

    void append(String entry) { entries.add(entry); }
    int size() { return entries.size(); }
}

// ─── ENUM SINGLETON: immune to serialization/reflection second instance ───
enum EnumAuditLedger {
    INSTANCE;
    private final List<String> entries = Collections.synchronizedList(new ArrayList<>());
    public void append(String entry) { entries.add(entry); }
    public int size() { return entries.size(); }
}

