package com.bank.singletondefense;

import java.lang.reflect.Constructor;
import java.util.logging.*;

public class DefenseDemo {
    private static final Logger log = Logger.getLogger(DefenseDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TxnSequence gen = TxnSequence.getInstance();
        log.info(() -> "First id : " + gen.next());   // TXN-1
        log.info(() -> "Second id: " + gen.next());   // TXN-2

        // ATTACK 1 — cloning: overridden clone() throws
        try {
            gen.attemptClone();
        } catch (CloneNotSupportedException e) {
            log.warning("Clone blocked: " + e.getMessage());
        }

        // ATTACK 2 — reflection: constructor guard throws
        try {
            Constructor<TxnSequence> c = TxnSequence.class.getDeclaredConstructor();
            c.setAccessible(true);
            c.newInstance();
            log.severe("Reflection created a SECOND instance (should not happen)");
        } catch (Exception e) {
            log.warning("Reflection blocked: " + rootCause(e));
        }

        // The single instance kept its sequence intact
        log.info(() -> "Third id : " + TxnSequence.getInstance().next()); // TXN-3

        // ENUM: no guards needed; clone is final and throws, reflection forbidden
        log.info(() -> "Enum id  : " + EnumTxnSequence.INSTANCE.next());
    }

    private static String rootCause(Throwable t) {
        while (t.getCause() != null) t = t.getCause();
        return t.getMessage();
    }
}

// ─── Class-based Singleton with ALL defenses ───
class TxnSequence implements java.io.Serializable, Cloneable {
    private static final TxnSequence INSTANCE = new TxnSequence();
    private int counter = 0;

    // REFLECTION guard: throw if an instance already exists
    private TxnSequence() {
        if (INSTANCE != null) throw new IllegalStateException("TxnSequence already created");
    }
    static TxnSequence getInstance() { return INSTANCE; }
    synchronized String next() { return "TXN-" + (++counter); }

    // CLONE defense: refuse to produce a copy
    @Override protected Object clone() throws CloneNotSupportedException {
        throw new CloneNotSupportedException("TxnSequence is a singleton; cannot clone");
    }
    // helper so the demo can trigger clone() from outside the package
    void attemptClone() throws CloneNotSupportedException { this.clone(); }

    // SERIALIZATION defense: always resolve back to the single instance
    private Object readResolve() { return INSTANCE; }
}

// ─── Enum Singleton: clone final+throws, reflection forbidden, serialization safe ───
enum EnumTxnSequence {
    INSTANCE;
    private int counter = 0;
    public synchronized String next() { return "ETXN-" + (++counter); }
}

