interface AccountState { void withdraw(StatefulAccount a, BigDecimal amt); }
class ActiveState implements AccountState {
    public void withdraw(StatefulAccount a, BigDecimal amt){ a.debit(amt); }
}
class FrozenState implements AccountState {
    public void withdraw(StatefulAccount a, BigDecimal amt){ throw new IllegalStateException("Account frozen"); }
}
class StatefulAccount {
    private final String id; private BigDecimal balance; private AccountState state = new ActiveState();
    StatefulAccount(String id, BigDecimal bal){ this.id=id; this.balance=bal; }
    void debit(BigDecimal a){ balance = balance.subtract(a); }
    void credit(BigDecimal a){ balance = balance.add(a); }
    void withdraw(BigDecimal a){ state.withdraw(this, a); }
    void freeze(){ state = new FrozenState(); }
    void activate(){ state = new ActiveState(); }
    BigDecimal balance(){ return balance; }
}

