        log.info("=== CIBIL healthy: Rajesh applies ===");
        loanService.evaluate("SAV2001", new BigDecimal("300000"));

        log.info("=== CIBIL goes DOWN ===");
        cibil.setDown(true);
        for (int i = 1; i <= 4; i++) {
            loanService.evaluate("CUR3001", new BigDecimal("300000"));
        }

        log.info("=== Breaker now OPEN: fast-fail fallback ===");
        loanService.evaluate("CUR3001", new BigDecimal("300000"));

        log.info("=== Wait for reset, CIBIL recovers ===");
        Thread.sleep(2200);
        cibil.setDown(false);
        loanService.evaluate("SAV2001", new BigDecimal("300000")); // half-open trial
    }
