class CibilClient {
    private volatile boolean down = false;
    void setDown(boolean down) { this.down = down; }

    // Simulates calling an external credit-score API.
    int fetchScore(String accountId) {
        if (down) throw new RuntimeException("CIBIL service timeout");
        return 780; // healthy score
    }
}

// ─── Would be in resilience/CircuitBreaker.java ───
class CircuitBreaker {
    private static final Logger log = Logger.getLogger(CircuitBreaker.class.getName());
    enum State { CLOSED, OPEN, HALF_OPEN }

    private State state = State.CLOSED;
    private int failureCount = 0;
    private final int failureThreshold;
    private final long resetMillis;
    private long openedAt = 0;

    CircuitBreaker(int failureThreshold, long resetMillis) {
        this.failureThreshold = failureThreshold;
        this.resetMillis = resetMillis;
    }

    boolean allowRequest() {
        if (state == State.OPEN) {
            if (System.currentTimeMillis() - openedAt >= resetMillis) {
                state = State.HALF_OPEN;
                log.warning("Breaker -> HALF_OPEN (trial call permitted)");
                return true;
            }
            return false; // still open, fail fast
        }
        return true; // CLOSED or HALF_OPEN
    }

    void recordSuccess() {
        failureCount = 0;
        if (state != State.CLOSED) log.info("Breaker -> CLOSED (dependency healthy)");
        state = State.CLOSED;
    }

    void recordFailure() {
        failureCount++;
        if (state == State.HALF_OPEN || failureCount >= failureThreshold) {
            state = State.OPEN;
            openedAt = System.currentTimeMillis();
            log.severe(() -> "Breaker -> OPEN (failures=" + failureCount + ")");
        }
    }

    State getState() { return state; }
}

// ─── Would be in service/LoanService.java ───
class LoanService {
    private static final Logger log = Logger.getLogger(LoanService.class.getName());
    private final CibilClient cibil;
    private final CircuitBreaker breaker;

    LoanService(CibilClient cibil, CircuitBreaker breaker) {
        this.cibil = cibil;
        this.breaker = breaker;
    }

    void evaluate(String accountId, BigDecimal amount) {
        if (!breaker.allowRequest()) {
            fallback(accountId, amount, "breaker OPEN");
            return;
        }
        try {
            int score = cibil.fetchScore(accountId);
            breaker.recordSuccess();
            log.info(() -> "Loan for " + accountId + " Rs." + amount
                    + " evaluated with CIBIL score " + score + " -> APPROVED");
        } catch (RuntimeException ex) {
            breaker.recordFailure();
            log.log(Level.SEVERE, "CIBIL call failed for " + accountId, ex);
            fallback(accountId, amount, "CIBIL failure");
        }
    }

    // Fallback uses ONLY our own data — never calls the failing CIBIL service.
    private void fallback(String accountId, BigDecimal amount, String reason) {
        BigDecimal safeLimit = new BigDecimal("500000");
        if (amount.compareTo(safeLimit) <= 0) {
            log.warning(() -> "Fallback (" + reason + "): small loan Rs." + amount
                    + " for " + accountId + " -> APPROVED on internal history");
        } else {
            log.warning(() -> "Fallback (" + reason + "): large loan Rs." + amount
                    + " for " + accountId + " -> MANUAL REVIEW");
        }
    }
}

