    private static final Logger log = Logger.getLogger(PaymentService.class.getName());
    private final Set<String> refunded = new HashSet<>(); // idempotency guard

    void debitFee(String sagaId, String acct, BigDecimal fee) {
        log.info(() -> "[Payments] LOCAL TXN: debit fee Rs." + fee + " from " + acct);
    }

    // Compensation — idempotent: refunding twice has no extra effect.
    void refundFee(String sagaId, String acct, BigDecimal fee) {
        if (!refunded.add(sagaId)) {
            log.warning(() -> "[Payments] refund for " + sagaId + " already applied — skipping (idempotent)");
