class AccountPolicy {
    private final BigDecimal minBalance;
    private final BigDecimal belowMinFeeRate;
    AccountPolicy(BigDecimal minBalance, BigDecimal belowMinFeeRate) {
        this.minBalance = minBalance;
        this.belowMinFeeRate = belowMinFeeRate;
    }
    BigDecimal getMinBalance() { return minBalance; }

    boolean allowsWithdrawal(BigDecimal currentBalance, BigDecimal amount) {
        return currentBalance.subtract(amount).compareTo(minBalance) >= 0;
    }
    BigDecimal belowMinimumFee(BigDecimal balance) {
        if (balance.compareTo(minBalance) >= 0) return BigDecimal.ZERO;
        return balance.multiply(belowMinFeeRate);
    }
}

