        if (!policy.allowsWithdrawal(acc.getBalance(), amount)) {
            log.warning(() -> "Withdrawal Rs." + amount + " blocked for " + acc.getAccountId()
                    + " — would breach min balance Rs." + policy.getMinBalance());
            return;
