import java.util.logging.*;

public class ImmutableDemo {
    private static final Logger log = Logger.getLogger(ImmutableDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<String> refs = new ArrayList<>(List.of("UTR-1001", "UTR-1002"));
        TransferRecord record = new TransferRecord(
                "SAV2001", "CUR3001", new BigDecimal("50000"),
                LocalDateTime.of(2026, 10, 26, 10, 15), refs);

        log.info(() -> "Created immutable record: " + record);

        // Attempt 1: mutate the list we passed IN — record must be unaffected.
        refs.add("UTR-HACK");
        log.info(() -> "After mutating the source list, record refs: " + record.getReferenceIds());

        // Attempt 2: mutate the list we got OUT — must throw or not affect record.
        try {
            record.getReferenceIds().add("UTR-HACK2");
        } catch (UnsupportedOperationException ex) {
            log.warning("Returned list is unmodifiable — mutation blocked (good).");
        }
        log.info(() -> "Record refs still: " + record.getReferenceIds());

        // "Change" = a NEW object, original untouched.
        TransferRecord repriced = record.withAmount(new BigDecimal("60000"));
        log.info(() -> "Original amount Rs." + record.getAmount()
                + ", new object amount Rs." + repriced.getAmount());
    }
}

// ─── Would be in model/TransferRecord.java ───
// IMMUTABLE: final class, private final fields, no setters, defensive copies.
final class TransferRecord {
    private final String fromId;
    private final String toId;
    private final BigDecimal amount;        // BigDecimal is already immutable
    private final LocalDateTime timestamp;  // LocalDateTime is already immutable
    private final List<String> referenceIds; // mutable → needs defensive copy

    TransferRecord(String fromId, String toId, BigDecimal amount,
                   LocalDateTime timestamp, List<String> referenceIds) {
        this.fromId = fromId;
        this.toId = toId;
        this.amount = amount;
        this.timestamp = timestamp;
        // Defensive copy IN: caller cannot mutate our internal list afterward.
        this.referenceIds = List.copyOf(referenceIds);
    }

    String getFromId() { return fromId; }
    String getToId() { return toId; }
    BigDecimal getAmount() { return amount; }
    LocalDateTime getTimestamp() { return timestamp; }

    // Defensive copy OUT: returned list is unmodifiable.
    List<String> getReferenceIds() { return List.copyOf(referenceIds); }

    // "with" method: returns a NEW record, never mutates this one.
    TransferRecord withAmount(BigDecimal newAmount) {
        return new TransferRecord(fromId, toId, newAmount, timestamp, referenceIds);
    }

    @Override public String toString() {
        return "TransferRecord{" + fromId + "->" + toId + ", Rs." + amount
                + ", " + timestamp + ", refs=" + referenceIds + "}";
    }
}

