package com.bank.prototype;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PrototypeDemo {
    private static final Logger log = Logger.getLogger(PrototypeDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        rajesh.addTransaction(new Transaction("T1", new BigDecimal("5000")));
        rajesh.addTransaction(new Transaction("T2", new BigDecimal("8000")));

        log.info("=== SHALLOW copy trap ===");
        Account shallow = Account.shallowBroken(rajesh); // shares the SAME list — DANGER
        shallow.addTransaction(new Transaction("HYP", new BigDecimal("999999")));
        log.severe(() -> "After editing shallow copy, REAL account has "
                + rajesh.getTransactions().size() + " txns (corrupted!)");

        // Rebuild clean original for the correct demo.
        Account clean = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        clean.addTransaction(new Transaction("T1", new BigDecimal("5000")));
        clean.addTransaction(new Transaction("T2", new BigDecimal("8000")));

        log.info("=== Copy CONSTRUCTOR (deep, safe) ===");
        Account scenario = new Account(clean); // deep copy — independent list
        scenario.addTransaction(new Transaction("HYP", new BigDecimal("999999")));
        log.info(() -> "Scenario copy has " + scenario.getTransactions().size()
                + " txns, REAL account still has " + clean.getTransactions().size() + " (safe!)");
    }
}

// ─── Would be in model/Transaction.java ───
final class Transaction {
    private final String id;
    private final BigDecimal amount;
    Transaction(String id, BigDecimal amount) { this.id = id; this.amount = amount; }
    String getId() { return id; }
}

// ─── Would be in model/Account.java ───
// Preferred Prototype mechanism: a COPY CONSTRUCTOR (Bloch's recommendation).
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    private final List<Transaction> transactions; // mutable → must deep-copy

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        this.transactions = new ArrayList<>();
    }

    // COPY CONSTRUCTOR — explicit DEEP copy of the mutable list.
    Account(Account other) {
        this.accountId = other.accountId;
        this.holderName = other.holderName;
        this.balance = other.balance;
        this.transactions = new ArrayList<>(other.transactions); // new independent list
    }

    // WRONG on purpose: a shallow copy that SHARES the original's list.
    static Account shallowBroken(Account other) {
        Account copy = new Account(other.accountId, other.holderName, other.balance);
        copy.transactions.addAll(other.transactions);
        // Simulate the shallow trap by replacing with the SAME reference:
        return new AliasAccount(other);
    }

    void addTransaction(Transaction t) { transactions.add(t); }
    List<Transaction> getTransactions() { return transactions; }
    String getAccountId() { return accountId; }
}

// ─── Demonstrates the shared-reference (shallow) trap ───
class AliasAccount extends Account {
    private final List<Transaction> shared;
    AliasAccount(Account other) {
        super(other.getAccountId(), "Rajesh", new BigDecimal("1000000"));
        this.shared = other.getTransactions(); // SAME list object — the trap
    }
    @Override void addTransaction(Transaction t) { shared.add(t); }
    @Override List<Transaction> getTransactions() { return shared; }
}

