package com.bank.proxy;

import java.lang.reflect.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ProxyDemo {
    private static final Logger log = Logger.getLogger(ProxyDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountService real = new RealAccountService();

        // JDK DYNAMIC PROXY — this is the mechanism Spring AOP uses by default.
        AccountService proxy = (AccountService) Proxy.newProxyInstance(
                AccountService.class.getClassLoader(),
                new Class[]{ AccountService.class },           // must be an interface
                new CachingSecurityHandler(real, "TELLER"));   // the advice

        log.info("=== Caching proxy: first call hits backend, second is cached ===");
        log.info(() -> "Balance #1: Rs." + proxy.getBalance("SAV2001"));
        log.info(() -> "Balance #2: Rs." + proxy.getBalance("SAV2001")); // cached

        log.info("=== Protection proxy: unauthorised caller rejected ===");
        AccountService guest = (AccountService) Proxy.newProxyInstance(
                AccountService.class.getClassLoader(),
                new Class[]{ AccountService.class },
                new CachingSecurityHandler(real, "GUEST"));
        try {
            guest.withdraw("SAV2001", new BigDecimal("1000"));
        } catch (SecurityException ex) {
            log.warning("Access denied for GUEST — " + ex.getMessage());
        }
    }
}

// ─── Would be in service/AccountService.java ───
interface AccountService {
    BigDecimal getBalance(String accountId);
    void withdraw(String accountId, BigDecimal amount);
}

// ─── Would be in service/RealAccountService.java ───
class RealAccountService implements AccountService {
    private static final Logger log = Logger.getLogger(RealAccountService.class.getName());
    private final Map<String, BigDecimal> balances = new HashMap<>(Map.of(
            "SAV2001", new BigDecimal("1000000"),
            "CUR3001", new BigDecimal("250000")));

    public BigDecimal getBalance(String accountId) {
        slowBackend();
        log.info(() -> "[REAL] backend fetched balance for " + accountId);
        return balances.get(accountId);
    }
    public void withdraw(String accountId, BigDecimal amount) {
        balances.computeIfPresent(accountId, (k, v) -> v.subtract(amount));
        log.info(() -> "[REAL] withdrew Rs." + amount + " from " + accountId);
    }
    private void slowBackend() { try { Thread.sleep(50); } catch (InterruptedException ignored) {} }
}

// ─── Would be in proxy/CachingSecurityHandler.java ───
// A dynamic-proxy InvocationHandler: runs CACHING + ACCESS-CONTROL advice
// around EVERY method, exactly like Spring AOP advice around a bean.
class CachingSecurityHandler implements InvocationHandler {
    private static final Logger log = Logger.getLogger(CachingSecurityHandler.class.getName());
    private final AccountService target;
    private final String role;
    private final Map<String, Object> cache = new HashMap<>();

    CachingSecurityHandler(AccountService target, String role) {
        this.target = target; this.role = role;
    }

    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        // Protection proxy: only TELLER may withdraw.
        if (method.getName().equals("withdraw") && !"TELLER".equals(role)) {
            throw new SecurityException("role " + role + " cannot withdraw");
        }
        // Caching proxy: cache getBalance by account id.
        if (method.getName().equals("getBalance")) {
            String key = "bal:" + args[0];
            if (cache.containsKey(key)) {
                log.info(() -> "[PROXY] cache HIT for " + args[0]);
                return cache.get(key);
            }
            Object result = method.invoke(target, args); // delegate to real subject
            cache.put(key, result);
            log.info(() -> "[PROXY] cache MISS -> stored " + args[0]);
            return result;
        }
        return method.invoke(target, args); // default delegation
    }
}

