    public static void main(String[] args) {
        // ADAPTER: wrap the mismatched vendor API behind our interface.
        CreditScoreProvider credit = new CibilAdapter(new CibilLegacyApi());

        // FACADE: one simple entry point over four subsystem services.
        AccountOpeningFacade facade = new AccountOpeningFacade(
                new KycService(), new AccountRepository(),
                new CardIssuer(), new NotificationService(), credit);

        log.info("=== FACADE: open account via ONE method ===");
        facade.openAccount("SAV2001", "Rajesh", "ABCDE1234F");
    }
