        vault.addLocker(new Locker("L2", "MEDIUM"));
        vault.addLocker(new Locker("L3", "LARGE"));

        Customer rajesh = new Customer("SAV2001", "Rajesh");
        Customer priya = new Customer("CUR3001", "Priya");

        log.info("=== Book lockers (LLD model traced end to end) ===");
        Booking b1 = vault.book(rajesh, "MEDIUM");
