        if (b2 != null) log.info(() -> "Booked " + b2.getLocker().getId()
                + " for " + b2.getCustomer().getName() + " @ Rs." + b2.getPrice());

        log.info("=== No free MEDIUM left -> clean failure ===");
        Booking b3 = vault.book(priya, "MEDIUM"); // already taken
        if (b3 == null) log.warning("No free MEDIUM locker available");
    }
