// ─── service/LockerVault.java — manages lockers, finds a free one ───
class LockerVault {
    private static final Logger log = Logger.getLogger(LockerVault.class.getName());
    private final List<Locker> lockers = new ArrayList<>(); // composition: vault owns lockers
    private final PricingStrategy pricing;
    LockerVault(PricingStrategy pricing) { this.pricing = pricing; }

    void addLocker(Locker l) { lockers.add(l); }

    // Concurrency note: in a real multi-threaded vault, synchronize assignment.
    synchronized Booking book(Customer customer, String size) {
        for (Locker l : lockers) {
            if (!l.isOccupied() && l.getSize().equals(size)) {
                l.assign();                          // entity owns its state change
                BigDecimal price = pricing.price(size);
                return new Booking(customer, l, price);
            }
        }
        return null; // clean failure — no exception needed for a normal "none free"
    }
}

// ─── pricing/PricingStrategy.java — Strategy ONLY because pricing truly varies ───
interface PricingStrategy {
    BigDecimal price(String size);
}

// ─── pricing/SizePricing.java ───
class SizePricing implements PricingStrategy {
    public BigDecimal price(String size) {
        switch (size) {
            case "SMALL":  return new BigDecimal("1500");
            case "MEDIUM": return new BigDecimal("3000");
            case "LARGE":  return new BigDecimal("5000");
            default:       return new BigDecimal("3000");
        }
    }
}

